head.script:
scwin.trigger1_onclick = function(e) {
    tabControl1.disableTab(1);
};
scwin.trigger2_onclick = function(e) {
    tabControl1.enableTab(1);
};
scwin.tabs2_onclick = function() {
    debugger;
};
scwin.selectbox1_onclick = function(e) {
    debugger;
};
scwin.checkVal = function() {
    if (WebSquare.wUnit.getJq('#wq_uuid_11').length == 0) {
        return WebSquare.wUnit.getJq('#wq_uuid_8_wq_uuid_11').hasClass('w2input_disabled');
    } else {
        return WebSquare.wUnit.getJq('#wq_uuid_11').hasClass('w2input_disabled');
    }
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 tab2 클릭하고 disable true를 클릭한다.
    //1. After running the sample file, click tab2 and click disable true.
    //WebSquare.wUnit.addCommand("set", "tabControl1_tab_tabs2.click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('tabControl1').setActiveTab(1)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. tab2와 콤보박스가 비활성화되어진다.
    //1. Tab2 and combo box are disabled.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('tabControl1').disableTab( 1 )");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#tabControl1_tab_tabs2').hasClass('w2tabcontrol_disabled')", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('selectbox1').getAttribute('disabled')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. disable false버튼을 클릭한다.
    //2. Click the disable false button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. tab2와 콤보박스가 활성화되어진다.(이전에는 wframe안의 inputbox도 활성화되어졌음)
    //2. Tab2 and the combo box are activated (previously the inputbox in the wframe is also activated)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#tabControl1_tab_tabs2').hasClass('w2tabcontrol_disabled')", "false");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('selectbox1').getAttribute('disabled')", "false");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //tabControl1.setSelectedTabIndex(1);
    autoComplete1.setDisabled(true);
    //autoComplete1.setSelectedIndex(-1);
    //selectbox1.setDisabled(true);
    //selectbox1.setSelectedIndex(-1);
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 27-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
